chapter:
 &reftitle.examples;


  基本的な curl の使用法

   PHP を cURL サポート機能付きでコンパイルすると、
   curl 関数を使用可能となります。cURL 関数の基本的な使用法は、
   curl_initにより cURL セッションを初期化、
   curl_setopt により転送時のオプションを設定、
   続いてcurl_exec
   により転送を実行するというものになります。



   cURL 関数を使用して POST リクエストを送信する簡単な例を示します。

    PHP の cURL モジュールを使用して POST リクエストを送信する


<?php
$data = ['foo' => 'bar', 'baz' => 48];
$url = "http://www.example.com/handler.php";

$ch = curl_init($url);

// レスポンスを標準出力に出力せず、戻り値として返すよう cURL に指示します
curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

// POST データと、対応するメソッドおよびヘッダーを設定します
curl_setopt($ch, CURLOPT_POSTFIELDS, http_build_query($data));

// リクエストを送信し、レスポンスを取得します
$response = curl_exec($ch);

if(curl_error($ch)) {
    // エラーを処理するか、単に例外をスローします
    throw new RuntimeException(curl_error($ch));
}






   cURL 関数を使用して、生の JSON を POST リクエストで送信する例も示します。

    PHP の cURL モジュールを使用して JSON を POST リクエストで送信する


<?php
$post_data = ['foo' => 'bar', 'baz' => 48];
$url = "http://www.example.com/api/endpoint";

$ch = curl_init($url);

// レスポンスを標準出力に出力せず、戻り値として返すよう cURL に指示します
curl_setopt($ch, CURLOPT_RETURNTRANSFER, true);

// POST データと、対応するメソッドを設定します
curl_setopt($ch, CURLOPT_POSTFIELDS, json_encode($post_data));

// 必要なヘッダーを設定します
curl_setopt($ch, CURLOPT_HTTPHEADER, ['Content-Type: application/json']);

// リクエストを送信し、レスポンスを取得します
$response = curl_exec($ch);

if(curl_error($ch)) {
    // エラーを処理するか、単に例外をスローします
    throw new RuntimeException(curl_error($ch));
}






   さらに、cURL 関数を使用して example.com ホームページをファイルに取得する例を示します。

    PHP の cURL モジュールを使用して example.com のホームページを取得する


<?php

$ch = curl_init("http://www.example.com/");
$fp = fopen("example_homepage.txt", "w");

curl_setopt($ch, CURLOPT_FILE, $fp);
curl_setopt($ch, CURLOPT_HEADER, 0);

curl_exec($ch);
if(curl_error($ch)) {
    fwrite($fp, curl_error($ch));
}
fclose($fp);
